#include <string>
#include <openssl/rc4.h>

std::string computeUValue(std::string const& user_password, QPDF::EncryptionData const& data) {
    // Step 1: Retrieve the encryption key using the password and encryption data
    std::string encryption_key = data.generateKey(user_password);

    // Step 2: Prepare buffer for U value (assume 16 bytes for example)
    unsigned char u_buffer[16];
    for (size_t i = 0; i < sizeof(u_buffer); ++i) {
        u_buffer[i] = static_cast<unsigned char>(i);
    }

    // Step 3: Apply RC4 encryption using the encryption key to the buffer
    RC4_KEY rc4_key;
    RC4_set_key(&rc4_key, encryption_key.size(), reinterpret_cast<unsigned char const*>(encryption_key.c_str()));
    RC4(&rc4_key, sizeof(u_buffer), u_buffer, u_buffer);

    // Step 4: Convert the result to a hexadecimal string and return it
    std::string u_value;
    for (size_t i = 0; i < sizeof(u_buffer); ++i) {
        char buffer[3];
        sprintf(buffer, "%02x", u_buffer[i]);
        u_value += buffer;
    }

    return u_value;
}

