std::string computeUValue(std::string const& user_password, QPDF::EncryptionData const& data) {
    std::string key = getKey(user_password, data);
    std::vector<unsigned char> buffer(data.buffer_size);

    // Initialize buffer with default pattern
    for (size_t i = 0; i < buffer.size(); ++i) {
        buffer[i] = static_cast<unsigned char>(0x24);
