#include <string>
#include <vector>
#include <openssl/evp.h>

std::string computeUValue(std::string const& user_password, QPDF::EncryptionData const& data) {
    // Retrieve the encryption key using the password and encryption data
    std::vector<unsigned char> encryption_key = data.getKeyFromPassword(user_password);

    // Prepare a buffer for the U value
    std::vector<unsigned char> u_buffer(data.getUBufferSize());

    // Process the key with RC4 encryption to generate the U value
    RC4_KEY rc4_key;
    RC4_set_key(&rc4_key, encryption_key.size(), encryption_key.data());
    RC4(&rc4_key, u_buffer.size(), u_buffer.data(), u_buffer.data());

    // Convert the result to a hexadecimal string
    std::string u_value;
    for (unsigned char byte : u_buffer) {
        char hex[3];
        snprintf(hex, sizeof(hex), "%02x", byte);
        u_value += hex;
    }

    return u_value;
}
